  const P82OfflineService = { async prepare() { const assets = ['./personal-vocabulary-system.css?v=1', './data/personal-vocabulary-system.js?v=2', './vocabulary-daily-action.css?v=1', './data/vocabulary-daily-action.js?v=1', './personal-vocabulary-organization.css?v=1', './data/personal-vocabulary-organization.js?v=1']; if (!global.caches) return { cached: false, assets: 0 }; const cache = await global.caches.open('klearn-pack-p82-personal-vocabulary'); await Promise.all(assets.map((asset) => cache.add(asset).catch(() => null))); const current = userScoped?.(STORAGE_KEYS.offlinePacks) || []; saveUserScoped?.(STORAGE_KEYS.offlinePacks, [{ id: 'p82-my-vocabulary', title: 'My Vocabulary', type: 'personal-vocabulary', status: 'downloaded', downloadedAt: now() }, ...current.filter((item) => item.id !== 'p82-my-vocabulary')], 100); return { cached: true, assets: assets.length }; } };

